css:
.ceilingsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2330;
    background: linear-gradient(160deg, #f4f1ea 0%, #ece7db 100%);
    border-radius: 18px;
}

.ceilingsim-container * {
    box-sizing: border-box;
}

.ceilingsim-header {
    text-align: center;
    padding: 28px 20px 24px;
    background: linear-gradient(135deg, #16213e 0%, #233156 55%, #34406b 100%);
    color: #f5f1e6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(22, 33, 62, 0.32);
    border-bottom: 3px solid #c8a24a;
}

.ceilingsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f7f2e4;
}

.ceilingsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e8cf8e;
    background: rgba(200, 162, 74, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(200, 162, 74, 0.35);
}

.ceilingsim-subtitle {
    margin: 12px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dcd6c6;
}

.ceilingsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2b3450;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.ceilingsim-period-counter #currentDay,
.ceilingsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #16213e;
}

.ceilingsim-round-name {
    background: #e6dcc2;
    color: #16213e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.ceilingsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a2233;
    background: #f3dcdf;
    padding: 4px 12px;
    border-radius: 999px;
}

.ceilingsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.ceilingsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2dac8;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.07);
    border-top: 4px solid #c8a24a;
}

.ceilingsim-card-readiness { border-top-color: #b8860b; }
.ceilingsim-card-sponsor { border-top-color: #2f5d8a; }
.ceilingsim-card-network { border-top-color: #4a7c59; }
.ceilingsim-card-outcome { border-top-color: #7a4b8a; }

.ceilingsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b6552;
}

.ceilingsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16213e;
}

.ceilingsim-card-readiness .ceilingsim-value { color: #b8860b; }
.ceilingsim-card-sponsor .ceilingsim-value { color: #2f5d8a; }
.ceilingsim-card-network .ceilingsim-value { color: #4a7c59; }
.ceilingsim-card-outcome .ceilingsim-value { color: #7a4b8a; }

.ceilingsim-sublabel {
    font-size: 0.76rem;
    color: #8a8470;
    line-height: 1.35;
}

.ceilingsim-readiness-fail .ceilingsim-value { color: #8a2233; }
.ceilingsim-readiness-target .ceilingsim-value { color: #4a7c59; }

.ceilingsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16213e;
    color: #f0e9d6;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c8a24a;
}

.ceilingsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e8cf8e;
}

.ceilingsim-budget-over #budgetDisplay {
    color: #f3a6af;
}

.ceilingsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c8a24a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.05);
}

.ceilingsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
    color: #b8860b;
    font-weight: 800;
}

.ceilingsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16213e;
    margin-bottom: 6px;
}

.ceilingsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #36405a;
}

.ceilingsim-briefing-text strong { color: #2f5d8a; }
.ceilingsim-briefing-text em { color: #8a2233; font-style: italic; }

.ceilingsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2dac8;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.06);
}

.ceilingsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16213e;
    border-bottom: 2px solid #ece4d2;
    padding-bottom: 8px;
}

.ceilingsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #283150;
    margin: 14px 0 6px;
}

.ceilingsim-container select,
.ceilingsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cfc4a6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf7ef;
    color: #1d2330;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.ceilingsim-container select:focus,
.ceilingsim-container input[type="number"]:focus {
    outline: none;
    border-color: #c8a24a;
    box-shadow: 0 0 0 3px rgba(200, 162, 74, 0.18);
}

.ceilingsim-container select option {
    background-color: #ffffff;
    color: #1d2330;
}

.ceilingsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b8860b;
}

.ceilingsim-range-readout,
.ceilingsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f5d8a;
    margin-top: 4px;
}

.ceilingsim-range-readout span:last-child,
.ceilingsim-alloc-readout span:nth-child(2) {
    color: #b8860b;
    font-weight: 800;
}

.ceilingsim-hint {
    font-size: 0.8rem;
    color: #8a8470;
    margin-top: 4px;
    line-height: 1.4;
}

.ceilingsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.ceilingsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f1e4;
    border: 1px solid #e6dcc2;
    border-radius: 9px;
    padding: 8px 12px;
}

.ceilingsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #283150;
}

.ceilingsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.ceilingsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.ceilingsim-container .btn-primary {
    background: linear-gradient(135deg, #16213e 0%, #2f5d8a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #f7f2e4;
    box-shadow: 0 6px 16px rgba(22, 33, 62, 0.30);
}

.ceilingsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.ceilingsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cfc4a6;
    color: #6b6552;
}

.ceilingsim-coach {
    background: #16213e;
    color: #ede6d4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 33, 62, 0.24);
    border-left: 4px solid #c8a24a;
}

.ceilingsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8cf8e;
    margin-bottom: 8px;
}

.ceilingsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.ceilingsim-coach-body strong { color: #f0d894; }
.ceilingsim-coach-body em { color: #f3a6af; font-style: italic; }

.ceilingsim-history,
.ceilingsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2dac8;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.06);
}

.ceilingsim-history h3,
.ceilingsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16213e;
}

.ceilingsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #283150;
}

.ceilingsim-container table#usfHistoryTable th {
    background: #f0ead8;
    color: #16213e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d6ba;
}

.ceilingsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebde;
}

.ceilingsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7ef;
}

.ceilingsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .ceilingsim-container {
        padding: 14px;
    }
    .ceilingsim-header h1 {
        font-size: 1.7rem;
    }
    .ceilingsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .ceilingsim-value {
        font-size: 2rem;
    }
    .ceilingsim-clock {
        margin-left: 0;
    }
    .ceilingsim-period-counter {
        font-size: 0.88rem;
    }
    .ceilingsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .ceilingsim-alloc-row {
        flex-wrap: wrap;
    }
    .ceilingsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .ceilingsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.ceilingsim-completion { padding: 8px 4px 4px; }
.ceilingsim-cm-head { text-align: center; margin-bottom: 16px; }
.ceilingsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #c8a24a; }
.ceilingsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #e8cf8e; }
.ceilingsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #ffffff; }
.ceilingsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.ceilingsim-cm-yes { background: rgba(200,162,74,0.16); color: #c8a24a; border: 1px solid rgba(200,162,74,0.5); }
.ceilingsim-cm-no { background: rgba(138,34,51,0.18); color: #e58a97; border: 1px solid rgba(138,34,51,0.6); }
.ceilingsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.ceilingsim-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(47,93,138,0.14); border: 1px solid rgba(47,93,138,0.3); border-radius: 10px; padding: 10px 8px; text-align: center; }
.ceilingsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #7fb0e0; }
.ceilingsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #b9c2d0; text-transform: uppercase; letter-spacing: 0.03em; }
.ceilingsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #ffffff; }
.ceilingsim-cm-insights { margin: 0; padding-left: 20px; }
.ceilingsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #d7dde8; }

