    class CeilingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Breaking the Ceiling`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_READINESS = 38;   // perceived readiness: qualified but ranked 3rd
            this.START_SPONSOR = 3.0;    // sponsorship strength 3/10
            this.START_NETWORK = 40;     // % of exec committee reached meaningfully
            this.TARGET_READINESS = 65;  // perceived readiness the committee needs to award the seat
            this.CAPITAL_POOL = 100;     // fixed 8-week time + political capital pool (Round 2)
            // Damp the per-round readiness movement so a flawless game peaks below the 0..100 clamp.
            // Without this, strong play saturates readiness at 100 by Round 3 and later levers
            // (sponsor advocacy, backlash, a mis-diagnosis in R1) leave no trace on the headline KPI.
            // Keeps the ≥65 seat bar meaningful and ensures each common error stays measurably penalised.
            this.READINESS_SCALE = 0.55;

            // Concept truths.
            this.TRUE_GAP = `sponsorship`;
            this.TRUE_FRAME = `doublestandard`;
            this.TRUE_FOCUS = `deciders`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    readiness: this.START_READINESS,
                    sponsor: this.START_SPONSOR,
                    network: this.START_NETWORK,
                    outcome: 0,
                    capitalUsed: 0,
                    backlash: false,
                    declinedStretch: false,
                    seatWon: false,
                    readinessHistory: [this.START_READINESS],
                    sponsorHistory: [this.START_SPONSOR * 10],
                    networkHistory: [this.START_NETWORK],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gap: `sponsorship`,
                    frame: `doublestandard`,
                    focus: `deciders`,
                    changeable: 60,
                    sponsorMove: 35,
                    boardMove: 25,
                    steeringMove: 20,
                    networkMove: 20,
                    credit: `team`,
                    visibility: 55,
                    stretch: `scope`,
                    resources: 65,
                    metric: `documented`,
                    geo: `plan`,
                    case: `full`,
                    sponsorAct: `advocate`,
                    pipeline: `structural`,
                    pitch: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const frame = document.getElementById(`frameInput`);
                const focus = document.getElementById(`focusInput`);
                const ch = document.getElementById(`changeableInput`);
                if (gap) decisions.gap = gap.value;
                if (frame) decisions.frame = frame.value;
                if (focus) decisions.focus = focus.value;
                if (ch) decisions.changeable = parseInt(ch.value, 10);
                if (!Number.isFinite(decisions.changeable) || decisions.changeable < 0 || decisions.changeable > 100) {
                    warn(`warn_changeable_range`); return false;
                }
            } else if (round === 2) {
                const sm = document.getElementById(`sponsorMoveInput`);
                const bm = document.getElementById(`boardMoveInput`);
                const stm = document.getElementById(`steeringMoveInput`);
                const nm = document.getElementById(`networkMoveInput`);
                if (sm) decisions.sponsorMove = parseFloat(sm.value);
                if (bm) decisions.boardMove = parseFloat(bm.value);
                if (stm) decisions.steeringMove = parseFloat(stm.value);
                if (nm) decisions.networkMove = parseFloat(nm.value);
                const parts = [decisions.sponsorMove, decisions.boardMove, decisions.steeringMove, decisions.networkMove];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_capital_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0));
                if (total !== this.CAPITAL_POOL) {
                    warn(`warn_capital_total`); return false;
                }
                const cr = document.getElementById(`creditInput`);
                const vis = document.getElementById(`visibilityInput`);
                if (cr) decisions.credit = cr.value;
                if (vis) decisions.visibility = parseInt(vis.value, 10);
                if (!Number.isFinite(decisions.visibility) || decisions.visibility < 0 || decisions.visibility > 100) {
                    warn(`warn_visibility_range`); return false;
                }
            } else if (round === 3) {
                const st = document.getElementById(`stretchInput`);
                const res = document.getElementById(`resourcesInput`);
                const me = document.getElementById(`metricInput`);
                const geo = document.getElementById(`geoInput`);
                if (st) decisions.stretch = st.value;
                if (res) decisions.resources = parseInt(res.value, 10);
                if (me) decisions.metric = me.value;
                if (geo) decisions.geo = geo.value;
                if (!Number.isFinite(decisions.resources) || decisions.resources < 0 || decisions.resources > 100) {
                    warn(`warn_resources_range`); return false;
                }
            } else if (round === 4) {
                const ca = document.getElementById(`caseInput`);
                const sa = document.getElementById(`sponsorActInput`);
                const pi = document.getElementById(`pipelineInput`);
                const pit = document.getElementById(`pitchInput`);
                if (ca) decisions.case = ca.value;
                if (sa) decisions.sponsorAct = sa.value;
                if (pi) decisions.pipeline = pi.value;
                if (pit) decisions.pitch = parseInt(pit.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // readinessDelta = change in perceived promotion readiness (the headline KPI)
            // sponsorDelta   = change in sponsorship strength (0..10 scale)
            // networkDelta   = change in network reach into the committee (%)
            // outcomeDelta   = change in the negotiated-outcome KPI (stretch terms quality)
            // spend          = political capital consumed this round (Round 2 only)
            let readinessDelta = 0, sponsorDelta = 0, networkDelta = 0, outcomeDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;
            let backlashThisRound = false;

            if (round === 1) {
                // Diagnose: results were necessary, not sufficient (Common Error 1).
                if (d.gap === this.TRUE_GAP) {
                    readinessDelta += 8; sponsorDelta += 0.5; coachKey = `coach_r1_gap_right`;
                } else if (d.gap === `results`) {
                    readinessDelta -= 6; coachKey = `coach_r1_results`;
                } else if (d.gap === `confidence`) {
                    readinessDelta -= 4; coachKey = `coach_r1_confidence`;
                } else {
                    readinessDelta -= 5; coachKey = `coach_r1_tenure`;
                }

                // The "readiness vs potential" double standard must be named, not mistaken for a fair call.
                if (d.frame === this.TRUE_FRAME) {
                    readinessDelta += 7;
                    if (d.gap === this.TRUE_GAP) coachKey = `coach_r1_diag_sharp`;
                } else if (d.frame === `fair`) {
                    readinessDelta -= 6; coachKey = `coach_r1_fair`;
                } else if (d.frame === `ignore`) {
                    readinessDelta -= 7; coachKey = `coach_r1_ignore`;
                } else {
                    readinessDelta -= 2;
                }

                // Map the committee toward the deciders she does NOT know — that is where the vote sits.
                if (d.focus === this.TRUE_FOCUS) {
                    networkDelta += 4; readinessDelta += 3;
                } else if (d.focus === `allies`) {
                    networkDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r1_allies` : coachKey;
                } else {
                    readinessDelta -= 4; coachKey = `coach_r1_hr`;
                }

                // Diagnostic sharpness: change the changeable, not the fixed.
                if (d.changeable >= 60) { readinessDelta += 4; }
                else if (d.changeable <= 25) { readinessDelta -= 5; coachKey = `coach_r1_lowdiag`; }

                summaryKey = (d.gap === this.TRUE_GAP && d.frame === this.TRUE_FRAME) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Sponsorship & visibility moves under a fixed capital pool (Common Errors 2 & 5-of-visibility).
                const sM = d.sponsorMove, bM = d.boardMove, stM = d.steeringMove, nM = d.networkMove;
                spend = sM + bM + stM + nM;

                // Converting a mentor into a sponsor is the single highest-leverage move (sponsorship predicts promotion).
                sponsorDelta += sM * 0.055;        // up to ~+5.5 on 0..10 if fully funded
                if (sM >= 30) { readinessDelta += 6; }
                else if (sM <= 10) { sponsorDelta -= 0.3; coachKey = `coach_r2_nosponsor`; }

                // Substantive board visibility lifts perceived readiness (she presented once vs peers' 5 and 4).
                readinessDelta += bM * 0.18;       // up to ~+18 if fully funded
                if (bM >= 20) { networkDelta += 2; }

                // Cross-business steering group: substantive exposure + reach, modest.
                readinessDelta += stM * 0.10;
                networkDelta += stM * 0.10;

                // Network reach toward the decision-makers (start 40%).
                networkDelta += nM * 0.30;         // up to ~+30 percentage points if fully funded

                // The credit move — backlash-aware (Common Error of over-promotion).
                if (d.credit === `team`) {
                    readinessDelta += 6; coachKey = `coach_r2_creditteam`;
                } else if (d.credit === `self`) {
                    readinessDelta -= 4; backlashThisRound = true; coachKey = `coach_r2_creditself`;
                } else {
                    readinessDelta -= 3; coachKey = `coach_r2_creditsilent`;
                }

                // Visibility intensity: substantive in the middle; too high reads as campaigning -> backlash.
                if (d.visibility >= 40 && d.visibility <= 75) {
                    readinessDelta += 4;
                } else if (d.visibility > 85) {
                    readinessDelta -= 8; backlashThisRound = true; coachKey = `coach_r2_overvisible`;
                } else if (d.visibility < 25) {
                    readinessDelta -= 4;
                }

                // Balanced portfolio insight: sponsorship-led but not starving visibility or network.
                const sponsorLed = sM >= bM && sM >= stM && sM >= nM;
                if (sponsorLed && sM >= 30 && bM >= 15 && nM >= 15 && !backlashThisRound) {
                    coachKey = `coach_r2_balanced`;
                } else if (bM >= 50 || nM >= 50) {
                    coachKey = (coachKey === `coach_default` || coachKey === `coach_r2_creditteam`) ? `coach_r2_lopsided` : coachKey;
                }

                summaryKey = (sponsorLed && d.credit !== `self` && d.visibility <= 85) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Negotiate the stretch (Common Errors 3 & 4).
                if (d.stretch === `decline`) {
                    // Avoiding the stretch hardens the "not ready" frame; a peer takes it.
                    ds.declinedStretch = true;
                    readinessDelta -= 10; outcomeDelta += 8; coachKey = `coach_r3_decline`;
                    summaryKey = `sum_r3_decline`;
                } else if (d.stretch === `grab`) {
                    // Taking it raw = a glass cliff. Visibility up but terms are dangerous.
                    readinessDelta += 4;
                    outcomeDelta += 18 + (d.resources * 0.10); // weak base; negotiation can partly rescue
                    coachKey = `coach_r3_grab`;
                    summaryKey = `sum_r3_grab`;
                } else {
                    // Scope it: take on negotiated terms — the credible-promotion-case path.
                    readinessDelta += 9; sponsorDelta += 0.4;
                    outcomeDelta += 30 + (d.resources * 0.25); // strong base, rewarded by hard negotiation
                    coachKey = `coach_r3_scope`;
                    summaryKey = `sum_r3_scope`;
                }

                if (d.stretch !== `decline`) {
                    // How hard she negotiates resources/authority/timeline.
                    if (d.resources >= 60) { readinessDelta += 4; }
                    else if (d.resources <= 25) { readinessDelta -= 4; outcomeDelta -= 8; coachKey = `coach_r3_lowres`; }

                    // A documented success metric is what turns a glass cliff into a winnable mandate.
                    if (d.metric === `documented`) {
                        outcomeDelta += 16; readinessDelta += 3;
                        if (d.stretch === `scope`) coachKey = `coach_r3_structured`;
                    } else if (d.metric === `verbal`) {
                        outcomeDelta += 2;
                    } else {
                        outcomeDelta -= 14; readinessDelta -= 4; coachKey = `coach_r3_nometric`;
                    }

                    // De-risking the Mexico-Poland integration.
                    if (d.geo === `plan`) { outcomeDelta += 10; }
                    else if (d.geo === `optimism`) { outcomeDelta -= 8; coachKey = (coachKey === `coach_r3_scope` || coachKey === `coach_r3_structured`) ? `coach_r3_optimism` : coachKey; }
                    else { outcomeDelta -= 12; readinessDelta -= 3; coachKey = `coach_r3_offload`; }
                }
            } else if (round === 4) {
                // Committee decision + sustaining the win (Common Error 5: tokenism).
                switch (d.case) {
                    case `full`: readinessDelta += 10; networkDelta += 3; coachKey = `coach_r4_fullcase`; break;
                    case `resultsonly`: readinessDelta -= 4; coachKey = `coach_r4_resultsonly`; break;
                    case `lobby`: readinessDelta -= 6; backlashThisRound = true; coachKey = `coach_r4_lobby`; break;
                }

                // Sponsor advocacy in the room — the whole point of Round 2's conversion.
                if (d.sponsorAct === `advocate`) {
                    // Effect scales with sponsorship strength actually built.
                    readinessDelta += 6 + Math.round(ds.sponsor * 1.2);
                    coachKey = (d.case === `full`) ? `coach_r4_advocate` : coachKey;
                } else if (d.sponsorAct === `mention`) {
                    readinessDelta += 1;
                } else {
                    readinessDelta -= 6; coachKey = `coach_r4_absent`;
                }

                // Pipeline action — individual win tied to structural change.
                switch (d.pipeline) {
                    case `structural`: outcomeDelta += 12; readinessDelta += 3; break;
                    case `mentor`: outcomeDelta += 3; break;
                    case `none`: outcomeDelta -= 6; coachKey = `coach_r4_tokenism`; break;
                }

                // Pitch conviction — substantive, not self-promotion. Too high without a case reads as campaigning.
                if (d.pitch >= 50 && d.pitch <= 85) { readinessDelta += 4; }
                else if (d.pitch > 90 && d.case !== `full`) { readinessDelta -= 4; backlashThisRound = true; }

                summaryKey = (d.case === `full` && d.sponsorAct === `advocate` && d.pipeline === `structural`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply backlash flag (over-promotion / lobbying penalises readiness gains).
            if (backlashThisRound) {
                ds.backlash = true;
                readinessDelta -= 3;
            }

            // Resource accounting (capital pool only spent in Round 2).
            ds.capitalUsed = Math.min(this.CAPITAL_POOL, Math.round(ds.capitalUsed + spend));

            // Move the KPIs within bounds.
            ds.sponsor = Math.max(0, Math.min(10, Math.round((ds.sponsor + sponsorDelta) * 10) / 10));
            ds.network = Math.max(0, Math.min(100, Math.round(ds.network + networkDelta)));
            ds.outcome = Math.max(0, Math.min(100, Math.round(ds.outcome + outcomeDelta)));

            // Readiness is driven by its own delta PLUS spillover from sponsorship, reach and the stretch outcome:
            // strong sponsors and a credible mandate move what the committee perceives.
            const spillover = (sponsorDelta * 1.5) + (networkDelta * 0.10) + (outcomeDelta * 0.12);
            const readinessMove = (readinessDelta + spillover) * this.READINESS_SCALE;
            ds.readiness = Math.max(0, Math.min(100, Math.round(ds.readiness + readinessMove)));

            ds.readinessHistory.push(Math.round(ds.readiness));
            ds.sponsorHistory.push(Math.round(ds.sponsor * 10));
            ds.networkHistory.push(Math.round(ds.network));

            if (round === this.ROUNDS.length) {
                ds.seatWon = ds.readiness >= this.TARGET_READINESS;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                readiness: Math.round(ds.readiness),
                readinessDelta: Math.round(readinessMove),
                sponsor: Math.round(ds.sponsor * 10) / 10,
                sponsorDelta: Math.round(sponsorDelta * 10) / 10,
                network: Math.round(ds.network),
                networkDelta: Math.round(networkDelta),
                outcome: Math.round(ds.outcome),
                outcomeDelta: Math.round(outcomeDelta),
                capitalUsed: ds.capitalUsed,
                backlash: ds.backlash,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`readinessDisplay`, `domainState.readiness`, (v) => {
                const card = document.querySelector(`.ceilingsim-card-readiness`);
                if (card) {
                    card.classList.toggle(`ceilingsim-readiness-target`, Number(v) >= this.TARGET_READINESS);
                    card.classList.toggle(`ceilingsim-readiness-fail`, Number(v) < this.TARGET_READINESS);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`sponsorDisplay`, `domainState.sponsor`, (v) => Number(v).toFixed(1));
            uiManager.bind(`networkDisplay`, `domainState.network`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`outcomeDisplay`, `domainState.outcome`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.capitalUsed`, (v) => {
                const bar = document.querySelector(`.ceilingsim-budget-bar`);
                if (bar) bar.classList.toggle(`ceilingsim-budget-over`, Number(v) > this.CAPITAL_POOL + 0.001);
                return Math.round(Number(v)) + ` / 100`;
            });

            const self = this;

            // Range readouts.
            const bindRange = function(inputId, readoutId) {
                const inp = document.getElementById(inputId);
                const out = document.getElementById(readoutId);
                if (inp && out) {
                    out.textContent = inp.value;
                    inp.addEventListener(`input`, function() { out.textContent = inp.value; });
                }
            };
            bindRange(`changeableInput`, `changeableReadout`);
            bindRange(`visibilityInput`, `visibilityReadout`);
            bindRange(`resourcesInput`, `resourcesReadout`);

            // Capital pool live total (Round 2).
            const poolIds = [`sponsorMoveInput`, `boardMoveInput`, `steeringMoveInput`, `networkMoveInput`];
            const poolReadout = document.getElementById(`poolReadout`);
            const recompute = function() {
                let total = 0;
                poolIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (poolReadout) poolReadout.textContent = total;
                const bar = document.querySelector(`.ceilingsim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.CAPITAL_POOL) ? `#8a2233` : ``;
            };
            poolIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
                ceilingChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_readiness`, `Promotion Readiness`),
                                data: [],
                                borderColor: `#b8860b`,
                                backgroundColor: `rgba(184,134,11,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#b8860b`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_sponsor`, `Sponsorship Strength (×10)`),
                                data: [],
                                borderColor: `#2f5d8a`,
                                backgroundColor: `rgba(47,93,138,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f5d8a`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_network`, `Network Reach %`),
                                data: [],
                                borderColor: `#4a7c59`,
                                backgroundColor: `rgba(74,124,89,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#4a7c59`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#1d2330`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#6b6552` }, grid: { color: `rgba(22,33,62,0.08)` },
                                title: { display: true, text: `0–100`, color: `#6b6552` }
                            },
                            x: {
                                ticks: { color: `#6b6552` }, grid: { color: `rgba(22,33,62,0.06)` },
                                title: { display: true, text: `Round`, color: `#6b6552` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.readinessHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                ceilingChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.readinessHistory },
                        { data: ds.sponsorHistory },
                        { data: ds.networkHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const readiness = Math.round(ds.readiness);
            const sponsor = Math.round(ds.sponsor * 10) / 10;
            const network = Math.round(ds.network);
            const outcome = Math.round(ds.outcome);
            const composite = Math.round(
                Math.min(100, readiness) * 0.40 +
                Math.min(100, sponsor * 10) * 0.25 +
                network * 0.15 +
                outcome * 0.20
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.wonSeat && s.strongSponsor && s.goodTerms);
            const badge = met
                ? `<span class="ceilingsim-cm-badge ceilingsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="ceilingsim-cm-badge ceilingsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const riskBadge = s.backlash
                ? ` <span class="ceilingsim-cm-badge ceilingsim-cm-no">` + T(`cm_backlash`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const sponStr = (typeof s.sponsor === `number`) ? s.sponsor.toFixed(1) : String(s.sponsor || ``);
            const metrics = ``
                + `<div class="ceilingsim-cm-metric"><span class="ceilingsim-cm-mv">` + Math.round(s.readiness || 0) + `</span><span class="ceilingsim-cm-ml">` + T(`cm_m_readiness`) + `</span></div>`
                + `<div class="ceilingsim-cm-metric"><span class="ceilingsim-cm-mv">` + sponStr + `</span><span class="ceilingsim-cm-ml">` + T(`cm_m_sponsor`) + `</span></div>`
                + `<div class="ceilingsim-cm-metric"><span class="ceilingsim-cm-mv">` + Math.round(s.network || 0) + `%</span><span class="ceilingsim-cm-ml">` + T(`cm_m_network`) + `</span></div>`
                + `<div class="ceilingsim-cm-metric"><span class="ceilingsim-cm-mv">` + Math.round(s.outcome || 0) + `</span><span class="ceilingsim-cm-ml">` + T(`cm_m_outcome`) + `</span></div>`;
            return ``
                + `<div class="ceilingsim-completion">`
                +   `<div class="ceilingsim-cm-head">`
                +     `<div class="ceilingsim-cm-score">` + score + `<span class="ceilingsim-cm-score-max">/100</span></div>`
                +     `<div class="ceilingsim-cm-grade">` + grade + ` ` + badge + riskBadge + `</div>`
                +   `</div>`
                +   `<div class="ceilingsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="ceilingsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="ceilingsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const readiness = Math.round(ds.readiness);
            const sponsor = Math.round(ds.sponsor * 10) / 10;
            const network = Math.round(ds.network);
            const outcome = Math.round(ds.outcome);

            const wonSeat = readiness >= this.TARGET_READINESS;
            const strongSponsor = sponsor >= 6.5;
            const goodTerms = outcome >= 55;
            const composite = Math.round(
                Math.min(100, readiness) * 0.40 +
                Math.min(100, sponsor * 10) * 0.25 +
                network * 0.15 +
                outcome * 0.20
            );

            let performanceKey = `grade_nexttime`;
            if (wonSeat && strongSponsor && goodTerms && composite >= 75) performanceKey = `grade_breaks`;
            else if (wonSeat && strongSponsor) performanceKey = `grade_vp`;
            else if (wonSeat && ds.backlash) performanceKey = `grade_backlash`;
            else if (wonSeat) performanceKey = `grade_thin`;
            else if (readiness >= this.START_READINESS + 12) performanceKey = `grade_closer`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (wonSeat && strongSponsor && goodTerms) insights.push(window.mySimulation.t(`insight_full`));
            else if (wonSeat) insights.push(window.mySimulation.t(`insight_won`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (sponsor < 5) insights.push(window.mySimulation.t(`insight_lowsponsor`));
            if (ds.declinedStretch) insights.push(window.mySimulation.t(`insight_declined`));
            if (ds.backlash) insights.push(window.mySimulation.t(`insight_backlash`));
            if (network < 55) insights.push(window.mySimulation.t(`insight_lownetwork`));
            if (wonSeat && ds.coachMessages.length && outcome >= 55 && sponsor >= 6.5) insights.push(window.mySimulation.t(`insight_pipeline`));

            return {
                readiness: readiness,
                sponsor: sponsor,
                network: network,
                outcome: outcome,
                wonSeat: wonSeat,
                backlash: ds.backlash,
                strongSponsor: strongSponsor,
                goodTerms: goodTerms,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.backlash && state.currentPeriod >= 2) return window.mySimulation.t(`hint_backlash`);
            if (ds.sponsor < 4 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_sponsor`);
            if (ds.network < 45 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_network`);
            if (ds.declinedStretch) return window.mySimulation.t(`hint_declined`);
            if (state.currentPeriod >= 3 && ds.readiness < 50) return window.mySimulation.t(`hint_behind`);
            if (ds.readiness >= this.TARGET_READINESS && ds.sponsor >= 6.5) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.readiness`, label: `Readiness`, i18nKey: `col_readiness`, formatter: (v) => Math.round(v) },
                { key: `results.sponsor`, label: `Sponsor`, i18nKey: `col_sponsor`, formatter: (v) => Number(v).toFixed(1) },
                { key: `results.network`, label: `Network`, i18nKey: `col_network`, formatter: (v) => Math.round(v) + `%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

